package com.salespunch360.mobile.account

import kotlinx.serialization.json.*

data class SalesOption(val id:String,val name:String,val branchId:String?=null,val code:String?=null,val phone:String?=null,val rate:String?=null,val taxRate:String?=null,val trackInventory:Boolean=false,val trackingMode:String="NONE",val symbol:String?=null,val customerId:String?=null,val status:String?=null,val barcode:String?=null,val costPrice:String?=null,val isDefault:Boolean=false,val stateCode:String?=null,val pricing:JsonObject?=null)
data class SalesDocumentRow(val id:String,val type:String,val number:String,val party:String,val date:String,val status:String,val total:String,val balance:String="",val paymentStatus:String="")
data class PurchaseAllocationDraft(val allocationType:String="INVENTORY",val quantity:String="1",val projectId:String="",val projectBudgetLineId:String="",val warehouseId:String="",val materialTreatment:String="DIRECT_TO_PROJECT")
data class SalesLineDraft(val servicePeriodDays:String="",val lineType:String="PRODUCT",val sourceId:String="",val itemName:String="",val description:String="",val unitName:String="",val unitSymbol:String="",val quantity:String="1",val rate:String="",val discountType:String="",val discountValue:String="0",val taxRate:String="",val warehouseId:String="",val sourceCommercialLineId:String="",val stockReturnQuantity:String="0",val purchaseAllocations:List<PurchaseAllocationDraft> = emptyList(),val batchId:String="",val serialNumberId:String="",val originalLineId:String="",val itemCode:String="",val specification:String="",val cessRate:String="0")
data class SalesEditorDraft(val customFields:Map<String,String> = emptyMap(),val type:String="SALES_INVOICE",val branchId:String="",val customerId:String="",val sourceDocumentId:String="",val editingSourceId:String="",val issueDate:String=java.time.LocalDate.now().toString(),val dueDate:String="",val taxMode:String="EXCLUSIVE",val stateOfSupplyCode:String="",val projectId:String="",val notes:String="",val billingName:String="",val customerPoNumber:String="",val customerPoDate:String="",val transactionTime:String="",val ewayBillNumber:String="",val transactionTaxRate:String="",val transactionDiscount:String="",val reverseCharge:Boolean=false,val tcsRate:String="0",val receivedInFull:Boolean=false,val receivedEnabled:Boolean=false,val receivedAmount:String="",val paymentType:String="CASH",val chequeNumber:String="",val chequeDate:String="",val paymentReference:String="",val lines:List<SalesLineDraft> = listOf(SalesLineDraft()),val projectRequired:Boolean=false,val tdsRate:String="0",val freightAmount:String="0",val otherChargesAmount:String="0",val roundOffAmount:String="")
data class NumberingPreview(val branchId:String,val prefix:String="",val suffix:String="",val padding:Int=2,val nextSequence:Long=1)
data class SalesOptions(val updateSalePrice:Boolean=false,val invoiceCustomFields:List<JsonObject> = emptyList(),val batches:List<JsonObject> = emptyList(),val serials:List<JsonObject> = emptyList(),val customerAdvances:List<JsonObject> = emptyList(),val transactionDefaults:JsonObject=JsonObject(emptyMap()),val recentSalePrices:List<JsonObject> = emptyList(),val defaultStateCode:String="",val types:List<String> = emptyList(),val branches:List<SalesOption> = emptyList(),val customers:List<SalesOption> = emptyList(),val products:List<SalesOption> = emptyList(),val services:List<SalesOption> = emptyList(),val workPackages:List<SalesOption> = emptyList(),val warehouses:List<SalesOption> = emptyList(),val projects:List<SalesOption> = emptyList(),val units:List<SalesOption> = emptyList(),val sourceDocuments:List<JsonObject> = emptyList(),val numberingSeries:List<NumberingPreview> = emptyList(),val itemWiseDiscount:Boolean=true,val wholesalePrice:Boolean=true)
data class AccountSalesState(val salePriceDocumentId:String?=null,val loading:Boolean=true,val saving:Boolean=false,val query:String="",val typeFilter:String?=null,val rows:List<SalesDocumentRow> = emptyList(),val options:SalesOptions=SalesOptions(),val editor:SalesEditorDraft?=null,val detail:JsonObject?=null,val postingId:String?=null,val error:String?=null,val message:String?=null)
fun applyCreatedSaleCustomer(state:AccountSalesState,customer:SalesOption)=state.copy(saving=false,options=state.options.copy(customers=state.options.customers.filterNot{it.id==customer.id}+customer),editor=state.editor?.copy(customerId=customer.id))

internal fun JsonObject.str(key:String)=this[key]?.jsonPrimitive?.contentOrNull.orEmpty()
internal fun JsonObject.bool(key:String)=this[key]?.jsonPrimitive?.booleanOrNull?:false
internal fun JsonObject.option(rateKey:String="salePrice")=SalesOption(str("id"),str("name"),str("branchId").ifBlank{null},str("code").ifBlank{null},str("phone").ifBlank{null},str(rateKey).ifBlank{null},str("taxRate").ifBlank{null},bool("trackInventory"),str("trackingMode").ifBlank{"NONE"},str("symbol").ifBlank{null},str("customerId").ifBlank{null},str("status").ifBlank{null},str("barcode").ifBlank{null},str("costPrice").ifBlank{null},bool("isDefault"),str("stateCode").ifBlank{null},this["pricing"] as? JsonObject)
internal fun JsonObject.array(key:String)=(this[key] as? JsonArray)?.mapNotNull{it as? JsonObject}.orEmpty()

fun SalesOptions.transactionPreference(key:String,fallback:Boolean=false):Boolean = (transactionDefaults["transactionPreferences"] as? JsonObject)?.get(key)?.jsonPrimitive?.booleanOrNull?:fallback
fun SalesOptions.defaultSalesDraft(type:String,branchId:String,projectRequired:Boolean=false):SalesEditorDraft {
 val date=java.time.LocalDate.now();val days=transactionDefaults.str("defaultDueDays").toIntOrNull()?.coerceIn(0,365)?:0
 val terms=if(!transactionPreference("termsEnabled",true))"" else if(projectRequired)transactionDefaults.str("projectTerms").ifBlank{transactionDefaults.str("salesTerms")} else transactionDefaults.str("salesTerms")
 return SalesEditorDraft(type=type,branchId=branchId,projectRequired=projectRequired,issueDate=date.toString(),dueDate=if(days>0&&type=="SALES_INVOICE")date.plusDays(days.toLong()).toString() else "",notes=if(type=="SALES_INVOICE")terms else "",stateOfSupplyCode=defaultStateCode,receivedInFull=type=="SALES_INVOICE"&&transactionPreference("cashSaleByDefault"),transactionTime=if(transactionPreference("transactionTime"))java.time.LocalTime.now().withSecond(0).withNano(0).toString() else "")
}

fun saleLinesWithFreeItem(line:SalesLineDraft,freeQuantity:String,trackingMode:String,freeSerialId:String=""):List<SalesLineDraft> {
 val free=freeQuantity.ifBlank{"0"}.toBigDecimalOrNull()?:throw IllegalArgumentException("Enter a valid free quantity.")
 require(free.signum()>=0){"Free quantity cannot be negative."}
 if(trackingMode=="BATCH")require(line.batchId.isNotBlank()){ "Select Batch for this item." }
 if(trackingMode=="SERIAL"){
  require(line.quantity.toBigDecimalOrNull()?.compareTo(java.math.BigDecimal.ONE)==0&&line.serialNumberId.isNotBlank()){ "Select a serial number and use quantity 1." }
  if(free.signum()>0)require(free.compareTo(java.math.BigDecimal.ONE)==0&&freeSerialId.isNotBlank()&&freeSerialId!=line.serialNumberId){ "Select a different serial for the free item and use free quantity 1." }
 }
 return listOf(line)+if(free.signum()>0)listOf(line.copy(originalLineId="",quantity=free.toPlainString(),rate="0",discountType="",discountValue="0",serialNumberId=if(trackingMode=="SERIAL")freeSerialId else line.serialNumberId,description="Free item")) else emptyList()
}

fun salesDraftPayload(draft:SalesEditorDraft)=buildJsonObject{put("type",draft.type);if(draft.type=="SALES_INVOICE")putJsonObject("customFields"){draft.customFields.forEach{(key,value)->put(key,value)}};put("branchId",draft.branchId);put("partyId",draft.customerId);draft.sourceDocumentId.takeIf{it.isNotBlank()}?.let{put("sourceDocumentId",it)};put("issueDate",draft.issueDate);draft.dueDate.takeIf{it.isNotBlank()}?.let{put("dueDate",it)};put("taxMode",draft.taxMode);draft.stateOfSupplyCode.takeIf{it.isNotBlank()}?.let{put("stateOfSupplyCode",it)};draft.projectId.takeIf{it.isNotBlank()}?.let{put("projectId",it)};put("notes",draft.notes);draft.billingName.takeIf{it.isNotBlank()}?.let{put("billingName",it)};draft.customerPoNumber.takeIf{it.isNotBlank()}?.let{put("customerPoNumber",it)};draft.customerPoDate.takeIf{it.isNotBlank()}?.let{put("customerPoDate",it)};draft.transactionTime.takeIf{it.isNotBlank()}?.let{put("transactionTime",it)};draft.ewayBillNumber.takeIf{it.isNotBlank()}?.let{put("ewayBillNumber",it)};put("tcsRate",draft.tcsRate);put("tdsRate",draft.tdsRate);put("freightAmount",draft.freightAmount);put("otherChargesAmount",draft.otherChargesAmount);draft.roundOffAmount.takeIf{it.isNotBlank()}?.let{put("roundOffAmount",it)};put("reverseCharge",draft.reverseCharge);if(draft.type=="SALES_INVOICE"&&draft.editingSourceId.isBlank()){put("receivedInFull",draft.receivedInFull);put("receivedAmount",if(draft.receivedEnabled)draft.receivedAmount.ifBlank{"0"} else "0");put("paymentType",draft.paymentType);if(draft.paymentType=="CHEQUE"){put("chequeNumber",draft.chequeNumber.trim());put("chequeDate",draft.chequeDate);draft.paymentReference.takeIf{it.isNotBlank()}?.let{put("paymentReference",it)}}};putJsonArray("lines"){draft.lines.forEach{line->add(buildJsonObject{put("lineType",line.lineType);if(draft.editingSourceId.isNotBlank())line.originalLineId.takeIf{it.isNotBlank()}?.let{put("originalLineId",it)};line.servicePeriodDays.takeIf{it.isNotBlank()}?.let{value->val days=value.toIntOrNull();if(days!=null)put("servicePeriodDays",days)else put("servicePeriodDays",value)};line.sourceId.takeIf{it.isNotBlank()}?.let{put("sourceId",it)};line.itemName.takeIf{it.isNotBlank()}?.let{put("itemName",it)};put("description",line.description);put("specification",line.specification);line.itemCode.takeIf{it.isNotBlank()}?.let{put("itemCode",it)};put("cessRate",line.cessRate);line.unitName.takeIf{it.isNotBlank()}?.let{put("unitName",it)};line.unitSymbol.takeIf{it.isNotBlank()}?.let{put("unitSymbol",it)};put("quantity",line.quantity);line.rate.takeIf{it.isNotBlank()}?.let{put("rate",it)};if(draft.transactionDiscount.isNotBlank()){put("discountType","PERCENTAGE");put("discountValue",draft.transactionDiscount)}else line.discountType.takeIf{it.isNotBlank()}?.let{put("discountType",it);put("discountValue",line.discountValue)};draft.transactionTaxRate.ifBlank{line.taxRate}.takeIf{it.isNotBlank()}?.let{put("taxRate",it)};line.warehouseId.takeIf{it.isNotBlank()}?.let{put("warehouseId",it)};line.batchId.takeIf{it.isNotBlank()}?.let{put("batchId",it)};line.serialNumberId.takeIf{it.isNotBlank()}?.let{put("serialNumberId",it)};line.sourceCommercialLineId.takeIf{it.isNotBlank()}?.let{put("sourceCommercialLineId",it)};put("stockReturnQuantity",line.stockReturnQuantity)})}}}

fun savedSaleEditorDraft(doc:JsonObject):SalesEditorDraft{val lines=doc.array("lines").map{line->SalesLineDraft(originalLineId=line.str("id"),lineType=line.str("lineType"),servicePeriodDays=line.str("servicePeriodDays"),sourceId=line.str("productId").ifBlank{line.str("serviceId").ifBlank{line.str("workPackageId")}},itemName=line.str("itemName"),itemCode=line.str("itemCode"),specification=line.str("specification"),cessRate=line.str("cessRate").ifBlank{"0"},description=line.str("description"),unitName=line.str("unitName"),unitSymbol=line.str("unitSymbol"),quantity=line.str("quantity"),rate=line.str("rate"),discountType=line.str("discountType"),discountValue=line.str("discountValue"),taxRate=line.str("taxRate"),warehouseId=line.str("warehouseId"),batchId=line.str("batchId"),serialNumberId=line.str("serialNumberId"),stockReturnQuantity="0")};return SalesEditorDraft(customFields=(doc["customValues"] as? JsonObject)?.mapValues{it.value.jsonPrimitive.content}.orEmpty(),type="SALES_INVOICE",tdsRate=doc.str("tdsRate").ifBlank{savedSaleTaxRate(doc,"tdsAmount")},freightAmount=doc.str("freightAmount").ifBlank{"0"},otherChargesAmount=doc.str("otherChargesAmount").ifBlank{"0"},roundOffAmount=doc.str("roundOffAmount").ifBlank{"0"},reverseCharge=doc.bool("reverseCharge"),projectId=doc.str("projectId"),tcsRate=doc.str("tcsRate").ifBlank{savedSaleTaxRate(doc,"tcsAmount")},branchId=doc.str("branchId"),customerId=doc.str("partyId"),editingSourceId=doc.str("id"),issueDate=doc.str("issueDate").take(10),taxMode=doc.str("taxMode").ifBlank{"EXCLUSIVE"},stateOfSupplyCode=doc.str("stateOfSupplyCode"),notes=doc.str("notes"),billingName=doc.str("billingName"),customerPoNumber=doc.str("customerPoNumber"),customerPoDate=doc.str("customerPoDate").take(10),transactionTime=doc.str("transactionTime"),ewayBillNumber=doc.str("ewayBillNumber"),dueDate=doc.str("dueDate").take(10),lines=lines.ifEmpty{listOf(SalesLineDraft())})}

private fun savedSaleTaxRate(doc:JsonObject,key:String):String {
 val taxable=doc.str("taxableTotal").toBigDecimalOrNull()?:java.math.BigDecimal.ZERO
 val amount=doc.str(key).toBigDecimalOrNull()?:java.math.BigDecimal.ZERO
 return if(taxable.signum()>0)amount.multiply(java.math.BigDecimal("100")).divide(taxable,6,java.math.RoundingMode.HALF_UP).stripTrailingZeros().toPlainString() else "0"
}

fun duplicateSavedSaleDraft(doc:JsonObject,date:String=java.time.LocalDate.now().toString()):SalesEditorDraft{
    require(doc.str("type")=="SALES_INVOICE"){"Only Sale invoices can be duplicated here."}
    val source=savedSaleEditorDraft(doc)
    require(source.customerId.isNotBlank()&&source.branchId.isNotBlank()){"The original customer or branch is unavailable."}
    return source.copy(editingSourceId="",sourceDocumentId="",issueDate=date,dueDate="",customerPoNumber="",customerPoDate="",ewayBillNumber="",transactionTime="",roundOffAmount="0",receivedEnabled=false,receivedInFull=false,receivedAmount="",paymentReference="",chequeNumber="",chequeDate="",lines=source.lines.map{it.copy(originalLineId="",batchId="",serialNumberId="",sourceCommercialLineId="",stockReturnQuantity="0",purchaseAllocations=emptyList())})
}
